mod common;

use common::Session;
use serde_json::json;

#[test]
fn create_is_idempotent_only_for_identical_attributes() {
    let mut s = Session::new();
    s.create("jobs", json!({}));
    s.create("jobs", json!({"VisibilityTimeout": 30, "DelaySeconds": null}));
    assert_eq!(
        s.err(json!({"Command": "CreateQueue", "QueueName": "jobs", "Attributes": {"DelaySeconds": 1}})),
        "QueueAlreadyExists"
    );
}

#[test]
fn create_rule_order() {
    let mut s = Session::new();
    let create = |name: &str, attrs| json!({"Command": "CreateQueue", "QueueName": name, "Attributes": attrs});
    assert_eq!(s.err(create("a.fifo", json!({}))), "QueueNameInvalid");
    assert_eq!(s.err(create("a", json!({"Fifo": true}))), "QueueNameInvalid");
    assert_eq!(s.err(create("a", json!({"ContentBasedDeduplication": true}))), "InvalidParameterValue");
    assert_eq!(s.err(create("a", json!({"MaxReceiveCount": 3}))), "InvalidParameterValue");
    assert_eq!(s.err(create("a", json!({"DeadLetterQueue": "dlq", "MaxReceiveCount": 3}))), "QueueDoesNotExist");
    s.create("dlq.fifo", json!({"Fifo": true}));
    assert_eq!(
        s.err(create("a", json!({"DeadLetterQueue": "dlq.fifo", "MaxReceiveCount": 3}))),
        "InvalidParameterValue"
    );
    s.create("b.fifo", json!({"Fifo": true, "DeadLetterQueue": "dlq.fifo", "MaxReceiveCount": 3}));
    // An existing queue is compared before the dead-letter queue is looked up.
    assert_eq!(
        s.err(create("b.fifo", json!({"Fifo": true, "DeadLetterQueue": "nope.fifo", "MaxReceiveCount": 3}))),
        "QueueAlreadyExists"
