    s.ok(json!({"Command": "SetQueueAttributes", "QueueName": "a", "Attributes": {"DelaySeconds": 0}}));
    s.push("a", "two");
    s.ok(json!({"Command": "SendMessage", "QueueName": "a", "Body": "three", "DelaySeconds": 3}));
    assert_eq!(s.counts("a"), [1, 0, 2]);
